CREATE TABLE closet_item_photos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_id uuid NOT NULL REFERENCES closet_items(id) ON DELETE CASCADE, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, object_key text NOT NULL UNIQUE, content_type text NOT NULL, confidence text NOT NULL DEFAULT 'OBSERVED', created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE closet_item_photos ENABLE ROW LEVEL SECURITY; ALTER TABLE closet_item_photos FORCE ROW LEVEL SECURITY;
CREATE POLICY closet_item_photos_self ON closet_item_photos FOR ALL TO closet_app USING (user_id = nullif(current_setting('app.user_id',true),'')::uuid AND tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (user_id = nullif(current_setting('app.user_id',true),'')::uuid AND tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
GRANT SELECT, INSERT, DELETE ON closet_item_photos TO closet_app;
